`]})}),e.jsx(a,{title:"The arithmetic of a larger vocabulary",children:e.jsxs(t.p,{children:["Going from 8,192 to 32,768 entries adds 32,768 − 8,192 = 24,576 rows. At ",e.jsx(t.code,{children:"d_model = 512"})," each row has 512 parameters, so one table grows by 24,576 × 512 = 12,582,912 parameters. With a tied output head that is the whole increase. With an untied head both tables grow, by 25,165,824 parameters in total. Whether the change pays off depends on how much shorter the sequences become on the target data and on how downstream quality changes."]})})]}),e.jsxs(s,{title:"More rows shorten sequences but thin the training signal",accent:1,number:"11",children:[e.jsxs(t.table,{children:[e.jsx(t.thead,{children:e.jsxs(t.tr,{children:[e.jsx(t.th,{children:"Dimension"}),e.jsx(t.th,{children:"Effect"}),e.jsx(t.th,{children:"Measure"})]})}),e.jsxs(t.tbody,{children:[e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Model tables"}),e.jsxs(t.td,{children:[e.jsx(t.code,{children:"V · d_model"})," per table"]}),e.jsx(t.td,{children:"Parameters and memory"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Sequence length"}),e.jsx(t.td,{children:"Larger V may shorten a corpus"}),e.jsx(t.td,{children:"Token count, effective context"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Piece frequency"}),e.jsx(t.td,{children:"Signal spread over more pieces"}),e.jsx(t.td,{children:"Frequency and fragmentation"})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Decision"}),e.jsx(t.td,{children:"No size best everywhere"}),e.jsx(t.td,{children:"Target-language and domain samples"})]})]})]}),e.jsxs(t.ul,{children:[`
